-- generated by tools/gencatalog, do not edit by hand

CREATE TABLE employees (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    personnel_number VARCHAR(10) NOT NULL,
    family_name VARCHAR(100) NOT NULL,
    given_name VARCHAR(100) NOT NULL,
    middle_name VARCHAR(100),
    email VARCHAR(254) NOT NULL,
    username VARCHAR(64) NOT NULL,
    hire_date DATE NOT NULL,
    employment_state TEXT CHECK (employment_state IN ('EMPLOYED', 'DISMISSED')) NOT NULL DEFAULT 'EMPLOYED',
    dismissal_date DATE,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT chk_employees_dismissal CHECK (dismissal_date IS NULL OR dismissal_date >= hire_date)
);

CREATE TABLE employee_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    employee_id BIGINT       NOT NULL REFERENCES employees(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_employee_revisions_revision
        UNIQUE (employee_id, revision_number)
);

CREATE UNIQUE INDEX uq_employees_personnel_number
    ON employees (personnel_number);

CREATE UNIQUE INDEX uq_employees_email
    ON employees (email);

CREATE UNIQUE INDEX uq_employees_username
    ON employees (username);

CREATE INDEX idx_employees_active
    ON employees (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_employee_revisions_employee_id
    ON employee_revisions (employee_id);

CREATE INDEX idx_employee_revisions_covering_agg
    ON employee_revisions (employee_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_employee_revisions_changed_at
    ON employee_revisions (changed_at);

CREATE INDEX idx_employees_employment_state ON employees (employment_state) WHERE is_deleted = FALSE;

CREATE OR REPLACE VIEW v_expanded_employee AS
SELECT
    t.id,
    t.personnel_number,
    t.family_name,
    t.given_name,
    t.middle_name,
    t.email,
    t.username,
    t.hire_date,
    t.employment_state,
    t.dismissal_date,
    NULL::bigint AS org_unit_id,
    NULL::bigint AS position_id,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM employees t
LEFT JOIN (
    SELECT
        employee_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM employee_revisions
    GROUP BY employee_id
) agg ON agg.employee_id = t.id;

COMMENT ON TABLE employees IS
    'HR profiles of employees. The unit and the position come from the assignment in effect today. Stores the current state of each record.';

COMMENT ON TABLE employee_revisions IS
    'Immutable audit log of changes applied to employees. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_employee IS
    'Read-only view that enriches each employee with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
